const fs = require('fs');
const path = require('path');
const dir = '/home/node/site/src/content/posts/tr';
const enDir = '/home/node/site/src/content/posts/en';
const limit = Number($input.first().json.limit ?? 3) || 3;

if (!fs.existsSync(dir)) throw new Error('TR posts directory missing: ' + dir);
if (!fs.existsSync(enDir)) fs.mkdirSync(enDir, { recursive: true });

const all = fs.readdirSync(dir)
  .filter((f) => f.endsWith('.md'))
  .sort();

const pending = all.filter((f) => !fs.existsSync(path.join(enDir, f)));
const selected = pending.slice(0, limit);

if (selected.length === 0) {
  return [{ json: { skip: true, message: 'No pending TR posts without EN counterpart.' } }];
}

return selected.map((fileName) => ({
  json: {
    skip: false,
    fileName,
    slug: fileName.replace(/\.md$/, ''),
    filePath: path.join(dir, fileName),
    enPath: path.join(enDir, fileName),
  },
}));

const meta = $('Tek Tek Islem').item.json;
const raw = ($json.data || '').toString();
const match = raw.match(/^---\r?\n([\s\S]*?)\r?\n---\r?\n([\s\S]*)$/);
if (!match) throw new Error('Frontmatter parse failed for ' + meta.fileName);

const fmBlock = match[1];
const body = match[2].trim();
const fm = {};
for (const line of fmBlock.split(/\r?\n/)) {
  const m = line.match(/^([\w]+):\s*"?(.+?)"?\s*$/);
  if (m) fm[m[1]] = m[2].replace(/^"|"$/g, '');
}

return [{
  json: {
    ...meta,
    tr_title: fm.title || '',
    tr_description: fm.description || '',
    tr_kategori: fm.kategori || 'Teknoloji',
    pubDate: fm.pubDate || new Date().toISOString(),
    kaynak: fm.kaynak || '',
    coverImage: fm.coverImage || '',
    gorselFotografci: fm.gorselFotografci || '',
    gorselFotografciLink: fm.gorselFotografciLink || '',
    tr_body: body,
  },
}];

const src = $('TR Post Parse').item.json;
const raw = ($json.content?.[0]?.text || $json.text || '').trim();

function pick(label) {
  const re = new RegExp('^' + label + ':\\s*(.+)$', 'im');
  const m = raw.match(re);
  return m ? m[1].trim() : '';
}

const title = pick('TITLE');
const summary = pick('SUMMARY');
let category = pick('CATEGORY');
const bodyMatch = raw.match(/^BODY:\s*\n([\s\S]*)$/im);
const body = bodyMatch ? bodyMatch[1].trim() : '';

const map = {
  AI: 'AI',
  Technology: 'Technology',
  Security: 'Security',
  'Yapay Zeka': 'AI',
  Teknoloji: 'Technology',
  Güvenlik: 'Security',
};
category = map[category] || map[src.tr_kategori] || 'Technology';

if (!title || !body) {
  throw new Error('Claude translation parse failed for ' + src.fileName + '\n---\n' + raw.slice(0, 400));
}

const esc = (s) => (s || '').replace(/"/g, "'");
const markdown = `---\ntitle: "${esc(title)}"\npubDate: ${src.pubDate}\nkategori: "${category}"\ndescription: "${esc(summary.slice(0, 150))}"\nkaynak: "${esc(src.kaynak)}"\ncoverImage: "${esc(src.coverImage)}"\ngorselFotografci: "${esc(src.gorselFotografci)}"\ngorselFotografciLink: "${esc(src.gorselFotografciLink)}"\n---\n${body}\n`;

return [{
  json: {
    ...src,
    en_title: title,
    en_summary: summary,
    en_kategori: category,
    markdown_icerik: markdown,
    dosya_adi: src.slug,
  },
}];
